create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.AVQ_WERBUNG (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Pruefziffer, Counter) Regel: Neuer Artikel -> Counter +1.',
	DAT_AKTION_VON DATE NOT NULL COMMENT 'Werbung/Aktion gültig ab',
	DAT_AKTION_BIS DATE NOT NULL COMMENT 'Werbung/Aktion gültig bis',
	KJWO NUMBER(38,0) NOT NULL COMMENT 'Kalenderwoche',
	ANZ_TAGE_AKTION NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage Aktion',
	WTAG_ID_START NUMBER(38,0) NOT NULL COMMENT 'Wochentag (Aktion von)',
	WTAG_ID_ENDE NUMBER(38,0) NOT NULL COMMENT 'Wochentag (Aktion bis)',
	CLUSTER_DAUER_ID NUMBER(38,0) NOT NULL COMMENT 'Cluste für die Dauer, z. B. 1: 1 Tages-Aktionen, 2: 2-4 Tage (Wochenstart/-ende), 3: 5-9 Tage (Normal Wochenwerbung), 4: alles > 9 Tage',
	WERBEMITTEL_AVQ_TOP_PRIO_NR NUMBER(38,0) NOT NULL COMMENT 'Werbemittel (AVQ) mit der höchsten Priorität/ID',
	WERBEFLAECHENABSCHNITT_AVQ_TOP_PRIO_NR NUMBER(38,0) NOT NULL COMMENT 'Werbeflächenabschnitt (AVQ) mit der höchsten Priorität/ID',
	WERBEFLAECHENTHEMA_AVQ_TOP_PRIO_NR NUMBER(38,0) NOT NULL COMMENT 'Werbeflächenthema (AVQ) mit der höchsten Priorität/ID',
	ART_MUTTER_WB_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel ID Werbemutter',
	POSTEN_WB_ID VARCHAR(2) NOT NULL COMMENT 'Postenkennzeichen der Werbemutter',
	POSTEN_ID VARCHAR(2) NOT NULL COMMENT 'Postenkennzeichen des Einzelartikels',
	PMR_TOP_ART_FG NUMBER(38,0) NOT NULL COMMENT 'TOP-Artikel Flag (PMR)',
	WERBEPROZESS_ID NUMBER(38,0) NOT NULL COMMENT '0 - keine Mengenberechnung, 1 - WBS TP1, 2 - WBS TP2, 3 - WBS TP1+2, 4 - F&R',
	AKTIONSKLASSIFIZIERUNG_ID VARCHAR(10) NOT NULL COMMENT 'SA/AF/BBY/irrelevant da gänzlich gelöscht oder gesperrt / k. Preisaktivierung…',
	AKTIONSKLASSIFIZIERUNG_DET_ID NUMBER(38,0) NOT NULL COMMENT 'Prospekt/K-Card-only/BBY/Kombi',
	WRG_ID VARCHAR(3) NOT NULL COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	BETRAG_VK_AKTION_BRUTTO NUMBER(38,3) NOT NULL COMMENT 'Verkaufspreis in Aktion',
	BETRAG_VK_KCARD_BRUTTO NUMBER(38,3) NOT NULL COMMENT 'Verkaufspreis in Aktion für K-CARD Kunden',
	BETRAG_VOR_AKTION_BRUTTO NUMBER(38,3) COMMENT 'Verkaufspreis vor Aktion',
	FAKTOR_FLAKI NUMBER(38,6) NOT NULL COMMENT 'Umrechnungsfaktor Flasche in Kiste. (Flasche/Kiste)',
	MHD_ZEITRAUM NUMBER(38,0) NOT NULL COMMENT 'Dieses Feld gibt den standardmaessigen Mindesthaltbarkeitszeitraum für diesen Artikel in Tagen an (wird redundant aus der Tabelle art geladen).',
	PRZ_MIN_RESTLAUFZEIT_LAGER NUMBER(38,0) NOT NULL COMMENT 'Lagerprozentsatz. Gibt an, wieviel Prozent der Restlaufzeit noch nicht abgelaufen sein darf, wenn der Artikel vom Lager ausgeliefert wird (wird redundant aus der Tabelle art geladen).',
	MENGE_PLAN_WBS NUMBER(38,3) NOT NULL COMMENT 'Planmenge aus WBS',
	MENGE_PLAN_UPLOAD NUMBER(38,3) NOT NULL COMMENT 'Planmenge aus Upload ',
	WBS_ESTIMATION_ID NUMBER(38,0) NOT NULL COMMENT 'Estimation ID WBS',
	WBS_ADJUSTMENT_ID NUMBER(38,0) NOT NULL COMMENT 'Adjustment ID WBS',
	MENGE_BESTAND_AKTIONSSTART NUMBER(38,3) NOT NULL COMMENT 'Bestandsmenge zum Beginn der Aktion.',
	MENGE_BESTAND_AKTIONSENDE NUMBER(38,3) NOT NULL COMMENT 'Bestandsmenge am Ende der Aktion.',
	MENGE_UEBERBESTAND NUMBER(38,3) NOT NULL COMMENT 'Überbestand nach Aktion',
	MENGE_BESTAND_MIN_SICHERHEIT NUMBER(38,3) NOT NULL COMMENT 'Menge, die unterste Grenze für den Sicherheitsbestand angibt. angereichert aus art_wup_status_per (MARC).',
	MENGE_BESTAND_SOLL_MAX NUMBER(38,3) NOT NULL COMMENT 'Maximaler Sollbestand (PRWOG) (wird redundant aus der Tabelle art_wup_nachschub_per geladen).',
	MENGE_SOLLBESTAND NUMBER(38,3) NOT NULL COMMENT 'Sollbestand (wird redundant aus der Tabelle art_wup_status_per geladen) (MARC).',
	ANZ_NULLBESTAND_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Nullbestand waehrend des Aktionszeitraums.',
	ANZ_NULLBESTAND_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Nullbestände am ersten Aktions-Wochentag für den Artikel, bei Gültigkeit > 1 Woche können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their first day)',
	ANZ_NULLBESTAND_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Nullbestand in den ersten drei Aktionstagen für den Artikel innerhalb der Kalenderwoche (kjwo).',
	ANZ_MINUSBESTAND_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Minusbestand waehrend des Aktionszeitraums.',
	ANZ_MINUSBESTAND_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Minusbestand am ersten Tag des Aktionszeitraums.',
	ANZ_MINUSBESTAND_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Minusbestand während der ersten drei Tage des Aktionszeitraums.',
	ANZ_EXC209_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Nullbestand in Aktion',
	ANZ_EXC209_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Nullbestand am 1. Tag (F&R Exception)',
	ANZ_EXC209_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Nullbestand Tag 1-3 (F&R Exception)',
	ANZ_EXC214_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Negativbestand in Aktion (F&R Exception)',
	ANZ_EXC214_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Negativbestand am 1. Tag (F&R Exception)',
	ANZ_EXC214_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Negativbestand Tag 1-3 (F&R Exception)',
	MENGE_GESAMT NUMBER(38,3) NOT NULL COMMENT 'Absatz gesamt in Basis-ME',
	BETRAG_UMSATZ_GESAMT NUMBER(38,3) NOT NULL COMMENT 'Umsatz netto gesamt',
	MENGE_HISTORIE_AF NUMBER(38,3) NOT NULL COMMENT 'Durchschnittliche Abverkaufsmenge der letzten 6 aktionsfreien Wochen.',
	MENGE_NUR_TAG1 NUMBER(38,3) NOT NULL COMMENT 'Absatz Tag 1 in Basis-ME',
	MENGE_TAG_1_7BIS13 NUMBER(38,3) NOT NULL COMMENT 'Absatz Tag 1 bis 13 Uhr in Basis-ME',
	MENGE_WE_GESAMT NUMBER(38,3) NOT NULL COMMENT 'Wareneingang in der Werbewoche.',
	MENGE_WE_VOR_AKTION NUMBER(38,3) NOT NULL COMMENT 'Wareneingang vor Aktion',
	MENGE_WE_IN_AKTION NUMBER(38,3) NOT NULL COMMENT 'Wareneingang in der Werbewoche und der Vorwoche, nur zentrale Bestellarten.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	ANGEBOT_TYP_CD VARCHAR(10) COMMENT 'Alphanumerischer Code des Angebotstyps. Da die Werte aus der Detailebene aggregiert werden, wird bei abweichenden Werten anhand einer festgelegten fachlichen Priorität entschieden, welcher Wert auf Kopfebene ausgewiesen wird.',
	AKTION_TYP_ID VARCHAR(4) COMMENT 'Gibt die Art der Aktion an (z. B. KDN = App-Promotion, KDP = personalisiert, KDI = externer Partner). Bei abweichenden Werten auf Detailebene wird der finale Wert für die Kopfebene anhand einer festgelegten fachlichen Priorität ermittelt.',
	GESCHAEFTSVORFALL_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'Eindeutige ID eines Geschäftsvorfalls (z. B. 01). Bei abweichenden Werten aus den zugrundeliegenden Detail-Datensätzen entscheidet eine festgelegte fachliche Priorität über den ausgewiesenen Wert.',
	KONDITIONSART_ID VARCHAR(4) COMMENT 'Eindeutiger Fachschlüssel der Konditionsart. Bei abweichenden Werten auf Detailebene greift zur Aggregation auf die Kopfebene eine festgelegte fachliche Prioritätsregel.',
	RABATT_TYP_ID NUMBER(38,0) COMMENT 'ID des Rabatt-Typs, die die Art des gewährten Rabattes angibt (z. B. 1 = Normalpreis, 2 = Rabattpreis, 3 = Absoluter Rabatt). Bei abweichenden Werten auf Detailebene entscheidet eine fachliche Priorität.',
	ANZ_BONUSKAUF_BEZAHLT NUMBER(38,0) COMMENT 'Gibt bei Bonuskäufen die Anzahl der Artikel an, die bezahlt werden müssen. Zur Aggregation auf den Gesamt-Werbezeitraum wird hier die Summe (SUM) der zugehörigen Detailwerte gebildet.',
	ANZ_BONUSKAUF_KAUF NUMBER(38,0) COMMENT 'Gibt bei Bonuskäufen die Anzahl der Artikel an, die gekauft werden müssen, um die Bedingung zu erfüllen. Zur Aggregation auf die Kopfebene wird die Summe (SUM) der Detailwerte gebildet.',
	ANZ_BONUSKAUF_GRATIS NUMBER(38,0) COMMENT 'Gibt bei Bonuskäufen die Anzahl der Artikel an, die kostenlos erhalten werden. Da diese Tabelle aggregiert ist, wird hier die Summe (SUM) der Detailwerte ausgewiesen.',
	MENGE_BONUSKAUF_MIN NUMBER(38,5) COMMENT 'Gibt bei Bonuskäufen die absatzbezogene Mindestmenge an, die erreicht werden muss, um die Bonusbuy-Bedingung zu erfüllen. Bei abweichenden Detailwerten wird zur Aggregation das Maximum (MAX) ausgewiesen.',
	PROZ_BONUSKAUF_RABATT NUMBER(38,5) COMMENT 'Der prozentuale Rabatt bei einem Bonuskauf. Zur Aggregation auf den Gesamt-Werbezeitraum wird hier das Maximum (MAX) der Rabattprozente aus der Detailebene gebildet.',
	BETRAG_BONUSKAUF_RABATT NUMBER(38,5) COMMENT 'Der absolute Wert des Rabattes bei einem Bonuskauf. Da die Werte aus der Detailebene stammen, wird zur Aggregation auf die Kopfebene das Maximum (MAX) ausgewiesen.',
	LISTUNG_FG NUMBER(38,0) COMMENT 'Flag gibt an, ob für die Artikel-Markt-Kombination im gesamten Aktionszeitraum eine Listung vorlag. (aus SAP WLK1) Durch die Aggregation auf den Gesamtzeitraum wird hier das Maximum der Tageswerte ausgewiesen. 1 = Listung lag an mindestens einem Tag der Aktion vor, 0 = keine Listung im gesamten Zeitraum.',
	constraint PK_AVQ_WERBUNG primary key (MANDANT_ID, WUP_ID, NB_ID, ART_ID, DAT_AKTION_VON, DAT_AKTION_BIS)
)COMMENT='AVQ(Abverkaufsquote) Basistabelle - Kennzahlen und wichtige Attribute auf Ebene Markt/Artikel/Werbezeitraum'
;
